 anexo (se necessário) : Nenhum documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"Christmann Hilleshein Cardoso","requesterArea":"Não informado","openingDate":"2026-02-19 18:35:47","modifiedAt":"2026-10-05 16:42:49","priority":2,"type":1}',1791319122591,1791319122591) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
