INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','74853','Automação - Retorno Bancário','Não informado','Katia Rubia Reinaldo Campos','Fechado','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2026-03-04 14:47:43','Encerrada no GLPI','Dados do formulário Categoria 1) Título : AUTOMATIZAÇÃO DOS ARQUIVOS DE RETORNO BANCÁRIOS 2) Selecione o Sistema : SAP 3) Categoria : Sistemas > Melhoria 4) Urgência : Alta Entidades 5) Ramal : 5829 Descrição 6) Descrição : Prezados, boa tarde. Conforme definido na ultima reunião, estamos desmembrando o chamado 8381 . Neste arquivo estão os prints dos caminhos executados para importação das remessas de retorno na pasta da FINNET. A intenção é que o sistema faça esse retorno de forma automática. Temos uma observação quanto aos arquivos do Banco do Brasil (EXT001), antes de importar o retorno, temos que abrir o arquivo e verificar a existência de alguma tarifa PIX. Caso tenha, temos que alterar a chave D104 para D105, pois sem essa alteração o sistema classifica em uma conta que não é correspondente a tarifa. Dúvidas, estamos a disposição. Anexo 7) Insira anexo (se necessário) : Documento anexado','','','',0,0,'Médio',false,'{"id":74853,"title":"Automação - Retorno Bancário","objective":"Dados do formulário Categoria 1) Título : AUTOMATIZAÇÃO DOS ARQUIVOS DE RETORNO BANCÁRIOS 2) Selecione o Sistema : SAP 3) Categoria : Sistemas > Melhoria 4) Urgência : Alta Entidades 5) Ramal : 5829 Descrição 6) Descrição : Prezados, boa tarde. Conforme definido na ultima reunião, estamos desmembrando o chamado 8381 . Neste arquivo estão os prints dos caminhos executados para importação das remessas de retorno na pasta da FINNET. A intenção é que o sistema faça esse retorno de forma automática. Temos uma observação quanto aos arquivos do Banco do Brasil (EXT001), antes de importar o retorno, temos que abrir o arquivo e verificar a existência de alguma tarifa PIX. Caso tenha, temos que alterar a chave D104 para D105, pois sem essa alteração o sistema classifica em uma conta que não é correspondente a tarifa. Dúvidas, estamos a disposição. Anexo 7) Insira anexo (se necessário) : Documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"Katia Rubia Reinaldo Campos","requesterArea":"Não informado","openingDate":"2026-03-04 14:47:43","modifiedAt":"2026-10-05 16:42:50","priority":2,"type":2}',1791319122591,1791319122591) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
