INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','74883','Automação - Compensação Bancária','Não informado','Katia Rubia Reinaldo Campos','Fechado','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2026-03-04 15:22:45','Encerrada no GLPI','Dados do formulário Categoria 1) Título : AUTOMAÇÃO DE PROCESSO COMPENSAÇÃO BANCÁRIA AUTOMÁTICA - F-03 2) Selecione o Sistema : SAP 3) Categoria : Sistemas > Melhoria 4) Urgência : Alta Entidades 5) Ramal : 5829 Descrição 6) Descrição : Prezados, boa tarde. Conforme definido na ultima reunião, estamos desmembrando o chamado 8381. No arquivo estão os prints dos caminhos executados para automação do processo de compensação no SAP, para reduzir o esforço manual e minimizar erros de conciliação. Atualmente, o processo é executado manualmente conforme os prints em anexo . A intenção é configurar a regra de lançamento do sistema para compensação automaticamente as partidas. Dúvidas, estamos à disposição. Anexo 7) Insira anexo (se necessário) : Documento anexado','','','',0,0,'Médio',false,'{"id":74883,"title":"Automação - Compensação Bancária","objective":"Dados do formulário Categoria 1) Título : AUTOMAÇÃO DE PROCESSO COMPENSAÇÃO BANCÁRIA AUTOMÁTICA - F-03 2) Selecione o Sistema : SAP 3) Categoria : Sistemas > Melhoria 4) Urgência : Alta Entidades 5) Ramal : 5829 Descrição 6) Descrição : Prezados, boa tarde. Conforme definido na ultima reunião, estamos desmembrando o chamado 8381. No arquivo estão os prints dos caminhos executados para automação do processo de compensação no SAP, para reduzir o esforço manual e minimizar erros de conciliação. Atualmente, o processo é executado manualmente conforme os prints em anexo . A intenção é configurar a regra de lançamento do sistema para compensação automaticamente as partidas. Dúvidas, estamos à disposição. Anexo 7) Insira anexo (se necessário) : Documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Fechado","statusCode":6,"requester":"Katia Rubia Reinaldo Campos","requesterArea":"Não informado","openingDate":"2026-03-04 15:22:45","modifiedAt":"2026-10-05 16:42:51","priority":2,"type":2}',1791319122591,1791319122591) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
