INSERT INTO `demands` (`source`,`external_id`,`name`,`area`,`requester_name`,`source_status`,`source_entity`,`source_category`,`source_opened_at`,`stage`,`objective`,`solution`,`benefit`,`risk`,`estimated_cost`,`estimated_hours`,`impact`,`project_prioritized`,`raw_json`,`created_at`,`updated_at`) VALUES ('glpi','127409','Chamado Projeto','Não informado','Jose Johnathan Ferreira de Souza','Em atendimento','Bom Jesus > Projeto','Projeto > Estudo de Viabilidade','2026-10-03 10:44:32','Triagem','Dados do formulário Categoria 1) Título : Projeto de Modernização do Canteiro de Germinação 2) Categoria : Projeto > Estudo de Viabilidade 3) Urgência : Alta Entidade Descrição 4) Descreva sua solicitação : Solicito a avaliação e aprovação do projeto de modernização do canteiro de testes de germinação e vigor da Bom Jesus Sementes, conforme proposta anexa. O projeto prevê a implantação de canteiros elevados e a reorganização da infraestrutura, visando padronizar os protocolos de análise, melhorar a rastreabilidade dos lotes e proporcionar maior uniformidade nas condições de avaliação, fortalecendo a confiabilidade dos resultados e a tomada de decisões sobre a qualidade das sementes. A modernização também busca melhorar a ergonomia dos colaboradores, reduzindo agachamentos e flexões prolongadas durante o plantio e as leituras, além de facilitar a circulação, a limpeza e a execução das atividades. Na área comercial, a estrutura permitirá receber produtores, consultores e parceiros em um ambiente mais organizado e adequado às visitas técnicas, demonstrando o rigor dos nossos processos e apoiando ações de marketing, treinamentos e vendas. Trata-se de um investimento estratégico para ampliar a eficiência operacional, valorizar a equipe e manter a competitividade da Bom Jesus Sementes diante da evolução das estruturas de avaliação do mercado regional. Solicito o encaminhamento para análise técnica, definição do modelo, orçamento e programação da implantação, preservando a continuidade dos testes durante a execução. Anexo 5) Insira anexo (se necessário) : Documento anexado','','','',0,0,'Médio',false,'{"id":127409,"title":"Chamado Projeto","objective":"Dados do formulário Categoria 1) Título : Projeto de Modernização do Canteiro de Germinação 2) Categoria : Projeto > Estudo de Viabilidade 3) Urgência : Alta Entidade Descrição 4) Descreva sua solicitação : Solicito a avaliação e aprovação do projeto de modernização do canteiro de testes de germinação e vigor da Bom Jesus Sementes, conforme proposta anexa. O projeto prevê a implantação de canteiros elevados e a reorganização da infraestrutura, visando padronizar os protocolos de análise, melhorar a rastreabilidade dos lotes e proporcionar maior uniformidade nas condições de avaliação, fortalecendo a confiabilidade dos resultados e a tomada de decisões sobre a qualidade das sementes. A modernização também busca melhorar a ergonomia dos colaboradores, reduzindo agachamentos e flexões prolongadas durante o plantio e as leituras, além de facilitar a circulação, a limpeza e a execução das atividades. Na área comercial, a estrutura permitirá receber produtores, consultores e parceiros em um ambiente mais organizado e adequado às visitas técnicas, demonstrando o rigor dos nossos processos e apoiando ações de marketing, treinamentos e vendas. Trata-se de um investimento estratégico para ampliar a eficiência operacional, valorizar a equipe e manter a competitividade da Bom Jesus Sementes diante da evolução das estruturas de avaliação do mercado regional. Solicito o encaminhamento para análise técnica, definição do modelo, orçamento e programação da implantação, preservando a continuidade dos testes durante a execução. Anexo 5) Insira anexo (se necessário) : Documento anexado","entity":"Bom Jesus > Projeto","category":"Projeto > Estudo de Viabilidade","status":"Em atendimento","statusCode":2,"requester":"Jose Johnathan Ferreira de Souza","requesterArea":"","openingDate":"2026-10-03 10:44:32","modifiedAt":"2026-10-03 10:44:32","priority":4,"type":1}',1791319122591,1791319122591) ON CONFLICT (`source`,`external_id`) DO UPDATE SET `name`=excluded.`name`,`area`=excluded.`area`,`requester_name`=excluded.`requester_name`,`source_status`=excluded.`source_status`,`source_entity`=excluded.`source_entity`,`source_category`=excluded.`source_category`,`source_opened_at`=excluded.`source_opened_at`,`raw_json`=excluded.`raw_json`,`updated_at`=excluded.`updated_at`;
